  const checkEntry = (entry: unknown): string | undefined => {
    if (typeof entry !== 'object' || entry === null) return undefined
    const source = (entry as Record<string, unknown>).source
    if (typeof source !== 'object' || source === null) return undefined
    const sourceObj = source as Record<string, unknown>
    if (sourceObj.kind === 'user-question-reply' && typeof sourceObj.callId === 'string') {
      return sourceObj.callId
    }
    return undefined
  }
  for (const entry of inboxState?.['next-step'] ?? []) {
    const callId = checkEntry(entry)
    if (callId !== undefined) queuedCallIds.add(callId)
  }
  for (const entry of inboxState?.['next-turn'] ?? []) {
    const callId = checkEntry(entry)
    if (callId !== undefined) queuedCallIds.add(callId)
  }
}
for (const card of cards.values()) {
  // Remove cards with queued replies, as the answer has been submitted and is waiting to be admitted.
  if (card.pending.callId !== undefined && queuedCallIds.has(card.pending.callId)) {
    card.remove()
    continue
